/**
 * Flow-field pathfinding.
 *
 * An integration field is built with BFS from the goal (uniform cost, so
 * BFS = Dijkstra for 4-connected grids). A flow field then stores, for each
 * open cell, the direction to its lowest-integration-cost neighbor. Cells
 * that cannot reach the goal get a sentinel integration value and no
 * direction.
 */

export const INFINITY_SENTINEL = Number.POSITIVE_INFINITY;

export interface FlowField {
  /** Rows of the map. */
  readonly height: number;
  /** Columns of the map. */
  readonly width: number;
  /**
   * integration[y][x]: BFS distance (in steps) from cell (x, y) to the goal.
   * INFINITY_SENTINEL for unreachable cells and walls.
   */
  readonly integration: readonly (readonly number[])[];
  /**
   * flow[y][x]: index (into DIRS) of the neighbor with the lowest integration
   * cost, or null when the cell has no usable direction (wall, goal, or
   * unreachable).
   */
  readonly flow: readonly (readonly (number | null)[])[];
}

/** 4-connected movement: up, down, left, right. */
export const DIRS: readonly [number, number][] = [
  [-1, 0], // up
  [1, 0], // down
  [0, -1], // left
  [0, 1], // right
];

export function parseMap(map: string[]): { grid: string[][]; goal: { x: number; y: number } } {
  if (map.length === 0) throw new Error("Map must have at least one row");
  const width = map[0].length;
  let goal: { x: number; y: number } | null = null;
  const grid = map.map((row, y) => {
    if (row.length !== width) throw new Error(`Row ${y} has inconsistent width`);
    return [...row].map((ch, x) => {
      if (ch === "G") {
        if (goal) throw new Error("Multiple goals in map");
        goal = { x, y };
      }
      if (ch !== "#" && ch !== "-" && ch !== "G") throw new Error(`Bad char '${ch}' at (${x}, ${y})`);
      return ch;
    });
  });
  if (!goal) throw new Error("No goal 'G' in map");
  return { grid, goal };
}

export function buildFlowField(map: string[]): FlowField {
  const { grid, goal } = parseMap(map);
  const height = grid.length;
  const width = grid[0].length;

  // --- Integration field via BFS from G ---
  const integration: number[][] = Array.from({ length: height }, () =>
    Array.from({ length: width }, () => INFINITY_SENTINEL),
  );
  const queue: [number, number][] = [goal];
  integration[goal.y][goal.x] = 0;
  for (let head = 0; head < queue.length; head++) {
    const [cx, cy] = queue[head];
    const d = integration[cy][cx] + 1;
    for (const [dx, dy] of DIRS) {
      const nx = cx + dx;
      const ny = cy + dy;
      if (nx < 0 || ny < 0 || nx >= width || ny >= height) continue;
      if (grid[ny][nx] === "#") continue;
      if (integration[ny][nx] !== INFINITY_SENTINEL) continue;
      integration[ny][nx] = d;
      queue.push([nx, ny]);
    }
  }

  // --- Flow field: point at lowest-cost open neighbor ---
  const flow: (number | null)[][] = Array.from({ length: height }, () =>
    Array.from({ length: width }, () => null),
  );
  for (let y = 0; y < height; y++) {
    for (let x = 0; x < width; x++) {
      if (grid[y][x] === "#") continue;
      if (integration[y][x] === INFINITY_SENTINEL) continue;
      if (x === goal.x && y === goal.y) continue; // goal has nowhere to go
      let bestCost = integration[y][x];
      let bestDir: number | null = null;
      for (let i = 0; i < DIRS.length; i++) {
        const nx = x + DIRS[i][0];
        const ny = y + DIRS[i][1];
        if (nx < 0 || ny < 0 || nx >= width || ny >= height) continue;
        if (grid[ny][nx] === "#") continue;
        if (integration[ny][nx] < bestCost) {
          bestCost = integration[ny][nx];
          bestDir = i;
        }
      }
      flow[y][x] = bestDir;
    }
  }

  return { width, height, integration, flow };
}

