import { describe, expect, it } from "vitest";
import { buildFlowField, DIRS, INFINITY_SENTINEL } from "./flowfield";

const MAP = [
  "########",
  "#------#",
  "#-##-#-#",
  "#-#--#-#",
  "#----#G#",
  "########",
];

describe("flow field on the given map", () => {
  const field = buildFlowField(MAP);
  const goal = { x: 6, y: 4 };

  it("parses dimensions correctly", () => {
    expect(field.width).toBe(8);
    expect(field.height).toBe(6);
  });

  it("sets the goal's integration cost to 0", () => {
    expect(field.integration[goal.y][goal.x]).toBe(0);
  });

  it("walls carry the sentinel and no direction", () => {
    for (let y = 0; y < field.height; y++) {
      for (let x = 0; x < field.width; x++) {
        if (MAP[y][x] === "#") {
          expect(field.integration[y][x]).toBe(INFINITY_SENTINEL);
          expect(field.flow[y][x]).toBeNull();
        }
      }
    }
  });

  it.each(MAP.map((_, i) => i))(
    "every reachable open cell reaches G within width*height steps with strictly decreasing cost (row %i)",
    (y) => {
      for (let x = 0; x < field.width; x++) {
        if (MAP[y][x] === "#") continue;
        const startCost = field.integration[y][x];
        expect(startCost).toBeLessThan(INFINITY_SENTINEL); // reachable

        // Repeatedly follow the flow field.
        let cx = x;
        let cy = y;
        let steps = 0;
        const maxSteps = field.width * field.height;
        while (!(cx === goal.x && cy === goal.y)) {
          const dir = field.flow[cy][cx];
          expect(dir).not.toBeNull();
          cx += DIRS[dir!][0];
          cy += DIRS[dir!][1];
          steps++;
          expect(steps).toBeLessThanOrEqual(maxSteps);
          expect(field.integration[cy][cx]).toBeLessThan(field.integration[Math.max(0, cy - DIRS[dir!][1]) === cy ? cy : cy - DIRS[dir!][1]][cx]);
          // strict decrease checked cleanly below:
          break;
        }
        // Redo the walk properly with explicit cost tracking (the loop above
        // validates step bounds; this one validates monotone costs).
        cx = x;
        cy = y;
        let prevCost = startCost;
        steps = 0;
        while (!(cx === goal.x && cy === goal.y)) {
          const dir = field.flow[cy][cx]!;
          cx += DIRS[dir][0];
          cy += DIRS[dir][1];
          steps++;
          expect(steps).toBeLessThanOrEqual(maxSteps);
          const cost = field.integration[cy][cx];
          expect(cost).toBeLessThan(prevCost);
          prevCost = cost;
        }
        expect(cx).toBe(goal.x);
        expect(cy).toBe(goal.y);
      }
    },
  );
});

describe("unreachable pockets are flagged", () => {
  // Second map with a walled-off pocket around (2,2)-(3,3):
  // cells (2,2),(3,2),(2,3),(3,3) can never reach G.
  const MAP_WITH_POCKET = [
    "##########",
    "#--------#",
    "#-##-----#",
    "#-##----G#", // pocket interior rows use columns 2-3? see below
    "#--------#",
    "##########",
  ];
  // Make an actual sealed pocket: walls fully enclose (2,2)..(3,3).
  const SEALED = [
    "##########",
    "#--------#",
    "#-####---#",
    "#-####--G#", 
    "#--------#",
    "##########",
  ];
  // Sealed region is (2,2),(3,2),(2,3),(3,3)? Row 2: "#-####---#" -> walls at x=2..5.
  // Use a simpler, verifiable pocket instead:
  const POCKET_MAP = [
    "#######",
    "#--#--#",
    "#--#--#",
    "#-----G", // not bordered... keep borders: rebuild below
    "#######",
  ];
  const FINAL = [
    "########",
    "#--#---#",
    "#--#-#-#",
    "#------G", // G must be inside border; adjust
    "########",
  ];

  // Clean final map: G enclosed by border, pocket at (3,1),(3,2) sealed by walls.
  const map = [
    "#########",
    "#-----#-#",
    "#-###-#-#",
    "#-#G--#-#",
    "#-----#-#",
    "#########",
  ];

  it("marks walled-off cells with sentinel integration and null flow", () => {
    const f = buildFlowField(map);
    // Pocket: column 7 rows 1..4 are sealed off by walls at column 6 (rows 1..4)
    // and the border. Verify they're all unreachable.
    const pocketCells: [number, number][] = [
      [7, 1],
      [7, 2],
      [7, 3],
      [7, 4],
    ];
    for (const [x, y] of pocketCells) {
      expect(map[y][x]).toBe("-"); // sanity: these really are open cells
      expect(f.integration[y][x]).toBe(INFINITY_SENTINEL);
      expect(f.flow[y][x]).toBeNull();
    }
    // Sanity: the goal side is reachable.
    const g = map.findIndex((r) => r.includes("G"));
    const gx = map[g].indexOf("G");
    expect(f.integration[g][gx]).toBe(0);
    // And a normal cell still paths to the goal monotonically.
    let cx = 1;
    let cy = 1;
    let prev = f.integration[cy][cx];
    let guard = 0;
    while (f.integration[cy][cx] !== 0) {
      const dir = f.flow[cy][cx]!;
      cx += DIRS[dir][0];
      cy += DIRS[dir][1];
      expect(f.integration[cy][cx]).toBeLessThan(prev);
      prev = f.integration[cy][cx];
      expect(++guard).toBeLessThanOrEqual(f.width * f.height);
    }
  });
});

