import { describe, expect, it } from "vitest";
import { buildFlowField, DIRS, INFINITY_SENTINEL, FlowField } from "./flowfield";

const MAP = [
  "########",
  "#------#",
  "#-##-#-#",
  "#-#--#-#",
  "#----#G#",
  "########",
];

const GOAL = { x: 6, y: 4 };

/** Walk the flow field from (x, y), asserting step bound + strictly decreasing cost. */
function walkFrom(field: FlowField, x: number, y: number) {
  const maxSteps = field.width * field.height;
  const startCost = field.integration[y][x];
  expect(startCost).toBeLessThan(INFINITY_SENTINEL); // reachable

  let cx = x;
  let cy = y;
  let prevCost = startCost;
  let steps = 0;
  while (!(cx === GOAL.x && cy === GOAL.y)) {
    const dir = field.flow[cy][cx];
    expect(dir).not.toBeNull();
    cx += DIRS[dir!][0];
    cy += DIRS[dir!][1];
    steps++;
    expect(steps).toBeLessThanOrEqual(maxSteps);
    const cost = field.integration[cy][cx];
    expect(cost).toBeLessThan(prevCost);
    prevCost = cost;
  }
  return steps;
}

describe("flow field on the given map", () => {
  const field = buildFlowField(MAP);

  it("parses dimensions correctly", () => {
    expect(field.width).toBe(8);
    expect(field.height).toBe(6);
  });

  it("sets the goal's integration cost to 0 and gives it no direction", () => {
    expect(field.integration[GOAL.y][GOAL.x]).toBe(0);
    expect(field.flow[GOAL.y][GOAL.x]).toBeNull();
  });

  it("walls carry the sentinel integration and no direction", () => {
    for (let y = 0; y < field.height; y++) {
      for (let x = 0; x < field.width; x++) {
        if (MAP[y][x] === "#") {
          expect(field.integration[y][x], `wall at (${x},${y})`).toBe(INFINITY_SENTINEL);
          expect(field.flow[y][x], `wall at (${x},${y})`).toBeNull();
        }
      }
    }
  });

  // One test per row so failures pinpoint where they occurred.
  it.each(MAP.map((_, i) => i))(
    "every reachable open cell in row %i reaches G with strictly decreasing cost",
    (y) => {
      for (let x = 0; x < field.width; x++) {
        if (MAP[y][x] === "#") continue;
        const steps = walkFrom(field, x, y);
        expect(steps).toBe(field.integration[y][x]);
      }
    },
  );
});

describe("unreachable cells are flagged with sentinel + no direction", () => {
  // Second map inline in the test: column 7 is open but completely sealed off
  // by the wall at column 6 and the outer border — an unreachable pocket.
  const MAP_WITH_POCKET = [
    "#########",
    "#-----#-#",
    "#-----#-#",
    "#--G--#-#",
    "#-----#-#",
    "#########",
  ];

  it("pocket cells have INFINITY_SENTINEL cost and null flow", () => {
    const f = buildFlowField(MAP_WITH_POCKET);

    const pocketCells: [number, number][] = [
      [7, 1],
      [7, 2],
      [7, 3],
      [7, 4],
    ];
    for (const [x, y] of pocketCells) {
      expect(MAP_WITH_POCKET[y][x]).toBe("-"); // sanity: genuinely open
      expect(f.integration[y][x], `pocket cell (${x},${y})`).toBe(INFINITY_SENTINEL);
      expect(f.flow[y][x], `pocket cell (${x},${y})`).toBeNull();
    }

    // Sanity: the reachable region still paths correctly.
    const gx = MAP_WITH_POCKET[3].indexOf("G");
    expect(gx).toBe(3);
    expect(f.integration[3][gx]).toBe(0);
    let cx = 1;
    let cy = 1;
    let prev = f.integration[cy][cx];
    let guard = 0;
    while (f.integration[cy][cx] !== 0) {
      const dir = f.flow[cy][cx]!;
      cx += DIRS[dir][0];
      cy += DIRS[dir][1];
      expect(f.integration[cy][cx]).toBeLessThan(prev);
      prev = f.integration[cy][cx];
      guard++;
      expect(guard).toBeLessThanOrEqual(f.width * f.height);
    }
    expect(cx).toBe(gx);
    expect(cy).toBe(3);
  });
});

